import{_ as a,a0 as o,w as i,s as n,I as s,x as t,a1 as r,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"CIO 真正需要 DevOps 團隊做什麼？ | LCTT x X-CMD","titleTemplate":false,"description":"CIO 真正需要 DevOps 團隊做什麼？ | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CIO 真正需要 DevOps 團隊做什麼？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CIO 真正需要 DevOps 團隊做什麼？ | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171205 What DevOps teams really need from a CIO","title":"CIO 真正需要 DevOps 團隊做什麼？","tag":"201804","desc":""},"relativePath":"201804/20171205 What DevOps teams really need from a CIO.md","filePath":"[post].md"}'),O={name:"201804/20171205 What DevOps teams really need from a CIO.md"};function v(m,e,D,f,T,u){const p=o("Link");return i(),n("div",null,[e[18]||(e[18]=s("h1",{id:"cio-真正需要-devops-團隊做什麼",tabindex:"-1"},[t("CIO 真正需要 DevOps 團隊做什麼？ "),s("a",{class:"header-anchor",href:"#cio-真正需要-devops-團隊做什麼","aria-label":"Permalink to “CIO 真正需要 DevOps 團隊做什麼？”"},"​")],-1)),e[19]||(e[19]=s("blockquote",null,[s("p",null,"DevOps 團隊需要 IT 領導者關注三件事：溝通、技術債務和信任。")],-1)),e[20]||(e[20]=s("p",null,[s("img",{src:"https://enterprisersproject.com/sites/default/files/styles/620x350/public/cio_cloud_2.png?itok=wGdeAHVn",alt:""})],-1)),s("p",null,[e[2]||(e[2]=t("IT 領導者可以從大量的 ",-1)),r(p,{href:"https://enterprisersproject.com/tags/devops"},{default:l(()=>[...e[0]||(e[0]=[t("DevOps",-1)])]),_:1}),e[3]||(e[3]=t(" 材料和 ",-1)),r(p,{href:"https://www.redhat.com/en/insights/devops?intcmp=701f2000000tjyaAAA"},{default:l(()=>[...e[1]||(e[1]=[t("向 DevOps 轉變",-1)])]),_:1}),e[4]||(e[4]=t(" 所要求的文化挑戰中學習。但是，你在一個 DevOps 團隊面對長期或短期的團結挑戰的調整中 —— 一個 CIO 真正需要他們做的是什麼呢？",-1))]),e[21]||(e[21]=d('<p>在我與 DevOps 團隊成員的談話中，我聽到的其中一些內容讓你感到非常的意外。DevOps 專家（無論是內部團隊的還是外部團隊的）都希望將下列的事情放在你的 CIO 優先關注的級別。</p><h3 id="_1-溝通" tabindex="-1">1. 溝通 <a class="header-anchor" href="#_1-溝通" aria-label="Permalink to “1. 溝通”">​</a></h3><p>第一個也是最重要的一個，DevOps 專家需要面對面的溝通。一個經驗豐富的 DevOps 團隊是非常瞭解當前 DevOps 的趨勢，以及成功和失敗的經驗，並且他們非常樂意去分享這些信息。表達 DevOps 的概念是很困難的，因此，要在這種新的工作關係中保持開放，定期（不用擔心，不用每週）討論有關你的 IT 的當前狀態，如何評價你的溝通環境，以及你的整體的 IT 產業。</p><p>相反，你應該準備好與 DevOps 團隊去共享當前的業務需求和目標。業務不再是獨立於 IT 的東西：它們現在是驅動 IT 發展的重要因素，並且 IT 決定了你的業務需求和目標運行的效果如何。</p><p>注重參與而不是領導。在需要做決策的時候，你仍然是最終的決策者，但是，理解這些決策的最好方式是協作，這樣，你的 DevOps 團隊將有更多的自主權，並因此受到更多激勵。</p><h3 id="_2-降低技術債務" tabindex="-1">2. 降低技術債務 <a class="header-anchor" href="#_2-降低技術債務" aria-label="Permalink to “2. 降低技術債務”">​</a></h3><p>第二，力爭更好地理解技術債務，並在 DevOps 中努力降低它。你的 DevOps 團隊都工作於一線。這裏，“技術債務”是指在一個龐大的、不可持續發展的環境之中，通過維護和增加新功能而佔用的人力資源和基礎設備資源（查看 Rube Goldberg）。</p><p>CIO 常見的問題包括：</p><ul><li>為什麼我們要用一種新方法去做這件事情？</li><li>為什麼我們要在它上面花費時間和金錢？</li><li>如果這裏沒有新功能，只是現有組件實現了自動化，那麼我們的收益是什麼？</li></ul><p>“如果沒有壞，就不要去修理它”，這樣的事情是可以理解的。但是，如果你正在路上好好的開車，而每個人都加速超過你，這時候，你的環境就被破壞了。持續投入寶貴的資源去支撐或擴張拼湊起來的環境。</p><p>選擇妥協，並且一個接一個的打補丁，以這種方式去處理每個獨立的問題，結果將從一開始就變得很糟糕 —— 在一個不能支撐建築物的地基上，一層摞一層地往上堆。事實上，這種方法就像不斷地在電腦中插入壞磁盤一樣。遲早有一天，面對出現的問題你將會毫無辦法。在外面持續增加的壓力下，整個事情將變得一團糟，完全吞噬掉你的資源。</p><p>這種情況下，解決方案就是：自動化。使用自動化的結果是良好的可伸縮性 —— 每個維護人員在 IT 環境的維護和增長方面花費更少的努力。如果增加人力資源是實現業務增長的唯一辦法，那麼，可伸縮性就是白日做夢。</p><p>自動化降低了你的人力資源需求，並且對持續進行的 IT 提供了更靈活的需求。很簡單，對嗎？是的，但是你必須為遲到的滿意做好心理準備。為了在提高生產力和效率的基礎上獲得後端經濟效益，需要預先投入時間和精力對架構和結構進行變更。為了你的 DevOps 團隊能夠成功，接受這些挑戰，對 IT 領導者來説是非常重要的。</p><h3 id="_3-信任" tabindex="-1">3. 信任 <a class="header-anchor" href="#_3-信任" aria-label="Permalink to “3. 信任”">​</a></h3><p>最後，相信你的 DevOps 團隊並且一定要理解他們。DevOps 專家也知道這個要求很難，但是他們必須得到你的強大支持和你積極參與的意願。因為 DevOps 團隊持續改進你的 IT 環境，他們自身也在不斷地適應這些變化的技術，而這些變化通常正是 “你要去學習的經驗”。</p><p>傾聽，傾聽，傾聽他們，並且相信他們。DevOps 的改變是非常有價值的，而且也是值的去投入時間和金錢的。它可以提高效率、生產力、和業務響應能力。信任你的 DevOps 團隊，並且給予他們更多的自由，實現更高效率的 IT 改進。</p><p>新 CIO 的底線是：將你的 DevOps 團隊的潛力最大化，離開你的領導 “舒適區”，擁抱一個 “CIOps&quot; 的轉變。通過 DevOps 轉變，持續地與你的 DevOps 團隊共同成長，以幫助你的組織獲得長期的 IT 成功。</p><hr>',18)),s("p",null,[e[6]||(e[6]=t("via: ",-1)),r(p,{href:"https://enterprisersproject.com/article/2017/12/what-devops-teams-really-need-cio"},{default:l(()=>[...e[5]||(e[5]=[t("https://enterprisersproject.com/article/2017/12/what-devops-teams-really-need-cio",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("作者：",-1)),r(p,{href:"https://enterprisersproject.com/user/john-allessio"},{default:l(()=>[...e[7]||(e[7]=[t("John Allessio",-1)])]),_:1}),e[11]||(e[11]=t(" 譯者：",-1)),r(p,{href:"https://github.com/qhwdw"},{default:l(()=>[...e[8]||(e[8]=[t("qhwdw",-1)])]),_:1}),e[12]||(e[12]=t(" 校對：",-1)),r(p,{href:"https://github.com/wxy"},{default:l(()=>[...e[9]||(e[9]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[15]||(e[15]=t("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原創編譯，",-1)),r(p,{href:"https://linux.cn/"},{default:l(()=>[...e[14]||(e[14]=[t("Linux中國",-1)])]),_:1}),e[17]||(e[17]=t(" 榮譽推出",-1))])])}const b=a(O,[["render",v]]);export{x as __pageData,b as default};
